type CuratedCourseInput = Pick<Course, 'id'|'priceMAD'|'pointsCost'|'title'|'category'|'instructor'|'initials'|'videoId'|'resourceUrl'|'description'|'learningObjectives'|'color'> & { duration: string; mediaLanguage?: string; quiz?: Course['quiz']; chapters: { title: string; summary: string; url: string; videoId?: string; videoStart?: number; duration?: string; module?: string }[] }

function curatedCourse(input: CuratedCourseInput): Course {
  return {
    id: input.id, priceMAD: input.priceMAD, pointsCost: input.pointsCost, title: input.title, category: input.category, level: 'Débutant',
    duration: input.duration, instructor: input.instructor, initials: input.initials, publisher: `${input.instructor} · vidéo publique`,
    mediaLanguage: input.mediaLanguage ?? 'Anglais', color: input.color, videoId: input.videoId,
    sourceUrl: `https://www.youtube.com/watch?v=${input.videoId}`, resourceUrl: input.resourceUrl,
    description: input.priceMAD ? `${input.description} Le tarif affiché est fictif et sert uniquement à tester le parcours premium local.` : input.description,
    prerequisites: 'Un ordinateur, un navigateur récent et les bases décrites sur cette fiche. Les outils et ressources externes sont publiés par leurs auteurs.',
    learningObjectives: input.learningObjectives,
    curriculum: input.chapters.map((chapter,index)=>({ title: chapter.title, duration: chapter.duration ?? (index===0?'Aperçu · 5 min':'Leçon guidée'), module: chapter.module ?? (index===0?'Aperçu gratuit':`Module ${index}`), summary: chapter.summary, resourceUrl: chapter.url, ...(chapter.videoId?{videoId:chapter.videoId}:index===0?{videoId:input.videoId}:{}), ...(chapter.videoStart!==undefined?{videoStart:chapter.videoStart}:{}) })),
    quiz: input.quiz ?? { question: `Quel est le bon premier pas pour apprendre ${input.title.split(' ')[0]} ?`, options: [input.learningObjectives[0], 'Ignorer les erreurs et copier le résultat', 'Commencer par des outils avancés sans vérifier les bases'], answer: 0, explanation: 'Commencez par les fondamentaux et vérifiez chaque étape dans la documentation officielle.' },
  }
}

